function [c] = eci_to_ecef(jd_ut1)
%ECI_TO_ECEF  J2000 to the Earth-fixed frame: the IAU 1976 precession to the mean equator of date, then GMST about z
%   (nutation and polar motion left out).
%   jd_ut1: real[1] (passed a plain number)
%   returns c: real[1][3][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    c = zeros(3, 3);
    g = asils.models.caltime.gmst_iau82(jd_ut1);
    r = [([cos(g); sin(g); 0]).'; ([(-(sin(g))); cos(g); 0]).'; ([0; 0; 1]).'];
    c = asils.pc.mm(r, asils.models.caltime.precession_iau76(jd_ut1));
end
